const express = require('express');
const { Worker } = require('worker_threads');
const path = require('path');
const { authMiddleware } = require('../middleware/auth');
const knex = require('../db');

const app = express();

app.get('/api/vault/items/:itemId/decrypt', authMiddleware, async (req, res) => {
  const item = await knex('vault_items')
    .where({ id: req.params.itemId, owner_id: req.user.id })
    .first();
  if (!item) {
    return res.status(403).json({ error: 'Forbidden: unauthorized access to vault secret' });
  }

  const worker = new Worker(path.resolve(__dirname, '../workers/cryptoDecryptor.js'));

  worker.postMessage({
    command: 'DECRYPT_VAULT_PAYLOAD',
    vaultItemId: req.params.itemId
  });

  worker.once('message', (response) => {
    if (response.success) {
      res.json({ plaintextSecret: response.secret, itemMetadata: response.meta });
    } else {
      res.status(500).json({ error: 'Decryption failed' });
    }
  });
});
